            facts["penalty_lines"] = sum(1 for ln in tl if ln.line_type == "cancellation_penalty")
        else:
            customer_cancel += 1
            facts["penalty_lines"] = sum(1 for ln in tl if ln.line_type == "cancellation_penalty")
