const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  for (const [w, h, name] of [[1500, 1000, 'desktop'], [390, 844, 'mobile']]) {
    const p = await b.newPage({ viewport: { width: w, height: h } });
    const errors = [];
    p.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    p.on('pageerror', e => errors.push(String(e)));
    await p.goto('http://localhost:8000/');
    await p.fill('#login-token', 'dev-token'); await p.fill('#login-name', 'meera');
    await p.click('#login-form button[type=submit]');
    await p.waitForSelector('#conversations .conv');
    await p.click('#conversations .conv[data-rider="R027"]');
    await p.waitForTimeout(800);
    await p.screenshot({ path: `/home/claude/scratch/shots/${name}-chat.png`, fullPage: name === 'mobile' });
    await p.click('[data-tab="disputes"]'); await p.waitForTimeout(300);
    await p.screenshot({ path: `/home/claude/scratch/shots/${name}-disputes.png`, fullPage: false });
    await p.click('[data-tab="trace"]'); await p.waitForTimeout(300);
    await p.screenshot({ path: `/home/claude/scratch/shots/${name}-trace.png` });
    const sw = await p.evaluate(() => document.documentElement.scrollWidth);
    console.log(name, 'scrollWidth', sw, 'errors', JSON.stringify(errors));
    await p.close();
  }
  await b.close();
})();
EOF
