input.command:
SP=/tmp/claude-0/-home-claude/f3ea7b05-388a-5150-89ba-2c1361bd3ef5/scratchpad && docker compose down -v >/dev/null 2>&1 && docker compose up -d --wait >/dev/null 2>&1 && python3 evals/run.py http://localhost:8000 --reset none > $SP/eval_pop2.txt 2>&1; grep "Conversations passed" $SP/eval_pop2.txt
cat > /home/claude/scratch/shot2.js << 'EOF'
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1500, height: 1000 } });
  const errors = []; p.on('pageerror', e => errors.push(String(e))); p.on('console', m => { if (m.type()==='error') errors.push(m.text()); });
  await p.goto('http://localhost:8000/');
  await p.fill('#login-token', 'change-me-ops-token'); await p.fill('#login-name', 'meera');
  await p.click('#login-form button[type=submit]');
  await p.waitForSelector('#queue .item');
  // approve R016's Rs 425 approval through the UI
  const item = p.locator('#queue .item', { hasText: 'R016' }).first();
  await item.locator('input').fill('verified 5 unpaid orders');
  await item.locator('button[data-act=approve]').click();
  await p.waitForTimeout(2500);
  await p.click('#conversations .conv[data-rider="R016"]'); await p.waitForTimeout(700);
  await p.click('[data-tab="payments"]'); await p.waitForTimeout(400);
  await p.screenshot({ path: '/home/claude/scratch/shots/approve-payments.png' });
  await p.click('[data-tab="disputes"]'); await p.waitForTimeout(400);
  await p.screenshot({ path: '/home/claude/scratch/shots/approve-disputes.png' });
  await p.click('#conversations .conv[data-rider="R027"]'); await p.waitForTimeout(700);
  await p.screenshot({ path: '/home/claude/scratch/shots/r027-disputes.png' });
  await p.click('[data-tab="audit"]'); await p.waitForTimeout(300);
  await p.click('#conversations .conv[data-rider="R016"]'); await p.waitForTimeout(700);
  await p.screenshot({ path: '/home/claude/scratch/shots/audit.png' });
  console.log('errors', JSON.stringify(errors));
  await b.close();
})();
EOF
cd /home/claude/scratch && NODE_PATH=$(npm root -g) node shot2.js && curl -s "localhost:8081/v1/payouts?rider_id=R016"

